import React from 'react';
import { interpolate, useCurrentFrame, useVideoConfig } from 'remotion';

export interface TextItem {
  text: string;
  color?: string;
  fontSize?: number;
}

export interface WordByWordText16x9Props {
  texts?: TextItem[] | string[] | any;
  displayMode?: 'sequential' | 'stacked';
  textColor?: string;
  fontSize?: number;
  fontWeight?: number;
  translateDistance?: number;
  motionBlurAmount?: number;
  wordStagger?: number;
  enableMotionBlur?: boolean;
  enableScaleDolly?: boolean;
  animation?: 'ramp-up-rise' | 'ramp-down-drop' | 'kinetic-fade';
  durationFrames?: number;
  delayFrames?: number;
  scale?: number;
  className?: string;
}

const extractTextItems = (input: any, defaultColor = '#ffffff'): TextItem[] => {
  if (!input) return [];

  if (Array.isArray(input)) {
    return input
      .map((item) => {
        if (typeof item === 'string') return { text: item.trim(), color: defaultColor };
        if (item && typeof item === 'object') {
          const val =
            item.text ??
            item.title ??
            item.value ??
            item.name ??
            Object.values(item)[0] ??
            '';
          return {
            text: String(val).trim(),
            color: item.color || defaultColor,
            fontSize: item.fontSize,
          };
        }
        return { text: String(item).trim(), color: defaultColor };
      })
      .filter((i) => i.text.length > 0);
  }

  if (typeof input === 'object') {
    const values = Object.values(input);
    if (values.length > 0) {
      return extractTextItems(values, defaultColor);
    }
  }

  if (typeof input === 'string') {
    const clean = input.trim();
    if (!clean) return [];

    try {
      const parsed = JSON.parse(clean);
      const result = extractTextItems(parsed, defaultColor);
      if (result.length > 0) return result;
    } catch (_) {}

    if (clean.indexOf('text') !== -1) {
      const extracted: TextItem[] = [];
      const segments = clean.split('text');
      for (let i = 1; i < segments.length; i++) {
        const seg = segments[i];
        const colonIdx = seg.indexOf(':');
        if (colonIdx !== -1) {
          const afterColon = seg.slice(colonIdx + 1).trim();
          const quoteChar =
            afterColon.charAt(0) === "'" ? "'" : afterColon.charAt(0) === '"' ? '"' : null;
          if (quoteChar) {
            const secondQuote = afterColon.indexOf(quoteChar, 1);
            if (secondQuote !== -1) {
              const val = afterColon.slice(1, secondQuote).trim();
              if (val) extracted.push({ text: val, color: defaultColor });
            }
          }
        }
      }
      if (extracted.length > 0) return extracted;
    }

    const parts = clean
      .replace(/[{}\[\]'"]/g, '')
      .split(',')
      .map((s) => s.trim())
      .filter((s) => s.length > 0);

    if (parts.length > 0) {
      return parts.map((t) => ({ text: t, color: defaultColor }));
    }
  }

  return [];
};

export const WordByWordText16x9: React.FC<WordByWordText16x9Props> = ({
  texts,
  displayMode = 'sequential',
  textColor = '#ffffff',
  fontSize = 110,
  fontWeight = 800,
  translateDistance = 85,
  motionBlurAmount = 18,
  wordStagger = 4.5,
  enableMotionBlur = true,
  enableScaleDolly = true,
  animation = 'ramp-up-rise',
  durationFrames,
  delayFrames = 0,
  scale = 1.0,
  className = '',
}) => {
  let frame = 0;
  let fps = 30;
  let compositionDuration = 300;

  try {
    const vConfig = useVideoConfig();
    fps = vConfig.fps || 30;
    compositionDuration = vConfig.durationInFrames || 300;
  } catch (_) {}

  try {
    frame = useCurrentFrame();
  } catch (_) {}

  const totalDuration = Number(durationFrames) || compositionDuration;
  const activeDuration = Math.max(1, totalDuration - Number(delayFrames || 0));
  const currentFrame = Math.max(0, frame - Number(delayFrames || 0));

  const parsed = extractTextItems(texts, textColor);
  const defaultList: TextItem[] = [
    { text: 'ONE TWO THREE', color: textColor },
    { text: 'WORD BY WORD', color: textColor },
    { text: 'TEXT ANIMATION', color: textColor },
  ];
  const visibleTexts = parsed.length > 0 ? parsed : defaultList;
  const N = visibleTexts.length;

  const slotDuration = activeDuration / N;

  const renderPhrase = (item: TextItem, idx: number) => {
    const itemStart = idx * slotDuration;
    const itemEnd = (idx + 1) * slotDuration;
    const localFrame = currentFrame - itemStart;

    const entranceDuration = Math.max(18, Math.min(40, Math.floor(slotDuration * 0.28)));
    const exitDuration = Math.max(14, Math.min(30, Math.floor(slotDuration * 0.20)));
    const crossOverlap = N > 1 && idx < N - 1 ? Math.floor(exitDuration * 0.75) : 0;
    const exitStart = slotDuration - exitDuration;

    if (displayMode === 'sequential' && N > 1) {
      if (localFrame < -2 || currentFrame > itemEnd + crossOverlap + 2) {
        return null;
      }
    }

    const words = item.text.trim().split(/\s+/);
    const wordCount = words.length;

    const effectiveWordStagger = Math.min(
      Number(wordStagger || 4.5),
      (entranceDuration * 0.6) / Math.max(1, wordCount)
    );

    const itemFontSize = item.fontSize || fontSize;

    const dollyProgress = interpolate(
      Math.max(0, Math.min(slotDuration, localFrame)),
      [0, slotDuration],
      [0.98, 1.025],
      { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' }
    );
    const dollyScale = enableScaleDolly ? dollyProgress : 1.0;

    return (
      <div
        key={idx}
        className={`${displayMode === 'sequential' && N > 1 ? 'absolute inset-0' : 'relative'} flex items-center justify-center flex-wrap text-center select-none will-change-transform`}
        style={{
          fontFamily: "-apple-system, BlinkMacSystemFont, 'Montserrat', 'SF Pro Display', sans-serif",
          fontSize: `${itemFontSize}px`,
          fontWeight,
          letterSpacing: '-0.025em',
          lineHeight: 1.15,
          color: item.color || textColor,
          transform: `scale(${dollyScale})`,
          transformOrigin: 'center center',
        }}
      >
        {words.map((word, wordIdx) => {
          const wordDelay = wordIdx * effectiveWordStagger;

          const linearEntrance = interpolate(
            localFrame - wordDelay,
            [0, entranceDuration - wordDelay * 0.3],
            [0, 1],
            { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' }
          );
          const wordEntrance = 1 - Math.pow(1 - linearEntrance, 3.2);

          const exitWordDelay = wordIdx * (effectiveWordStagger * 0.4);
          const linearExit = interpolate(
            localFrame,
            [exitStart + exitWordDelay, exitStart + exitWordDelay + exitDuration],
            [0, 1],
            { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' }
          );
          const wordExit = Math.pow(linearExit, 2.2);

          const activeOpacity = Math.max(0, Math.min(1, wordEntrance * (1 - wordExit)));

          let yDir = 1;
          if (animation === 'ramp-down-drop') yDir = -1;
          if (animation === 'kinetic-fade') yDir = 0;

          const translateY =
            (1 - wordEntrance) * translateDistance * yDir -
            wordExit * (translateDistance * 0.45 * yDir);

          const velocityRatio = Math.max(0, 1 - wordEntrance) + wordExit * 0.6;
          const verticalBlur = enableMotionBlur ? velocityRatio * motionBlurAmount : 0;
          const isLastWord = wordIdx === words.length - 1;

          return (
            <span
              key={wordIdx}
              className="inline-block whitespace-nowrap will-change-transform"
              style={{
                transform: `translate3d(0, ${translateY}px, 0)`,
                filter: verticalBlur > 0.5 ? `blur(0px ${verticalBlur}px)` : 'none',
                opacity: activeOpacity,
                marginRight: isLastWord ? '0px' : '0.35em',
              }}
            >
              {word}
            </span>
          );
        })}
      </div>
    );
  };

  return (
    <div
      className={`relative flex items-center justify-center select-none bg-transparent ${className}`}
      style={{
        width: '100%',
        minHeight: `${fontSize * 1.5}px`,
        transform: `scale(${Number(scale || 1)})`,
        transformOrigin: 'center center',
      }}
    >
      {displayMode === 'sequential' && N > 1 ? (
        <div className="relative w-full h-full flex items-center justify-center">
          {visibleTexts.map((item, idx) => renderPhrase(item, idx))}
        </div>
      ) : (
        <div className="flex flex-col items-center justify-center gap-6">
          {visibleTexts.map((item, idx) => renderPhrase(item, idx))}
        </div>
      )}
    </div>
  );
};

